export const RELEASE_ID_CONTRACT_SCHEMA = 'fsusblog.release-id-contract.v1'
export const RELEASE_ID_PATTERN = /^[0-9]{14}-[0-9a-f]{12}$/u
export const LOCAL_UNVERSIONED_RELEASE_ID = 'local-unversioned'

export interface ParsedReleaseId {
  releaseId: string
  createdAtUtc: string
  commitShaPrefix: string
}

export function parseReleaseId(value: string): ParsedReleaseId | null {
  if (!RELEASE_ID_PATTERN.test(value)) return null
  const timestamp = value.slice(0, 14)
  const year = Number(timestamp.slice(0, 4))
  const month = Number(timestamp.slice(4, 6))
  const day = Number(timestamp.slice(6, 8))
  const hour = Number(timestamp.slice(8, 10))
  const minute = Number(timestamp.slice(10, 12))
  const second = Number(timestamp.slice(12, 14))
  const date = new Date(Date.UTC(year, month - 1, day, hour, minute, second))
  const canonical = date.toISOString().replace(/[-:]/gu, '').replace('T', '').slice(0, 14)
  if (canonical !== timestamp) return null
  return {
    releaseId: value,
    createdAtUtc: date.toISOString().replace('.000Z', 'Z'),
    commitShaPrefix: value.slice(15)
  }
}

export function isCanonicalReleaseId(value: string): boolean {
  return parseReleaseId(value) !== null
}
